PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, base_url TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('approved','conditioned','rejected')), license TEXT, attribution TEXT, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_audits (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), audit_version TEXT NOT NULL, decision TEXT NOT NULL, assessed_at TEXT NOT NULL, coverage TEXT, access_method TEXT, limits TEXT, restrictions TEXT, storage_notes TEXT, personal_data_notes TEXT, risk_notes TEXT, cost_notes TEXT, alternative TEXT);
CREATE TABLE IF NOT EXISTS search_runs (id TEXT PRIMARY KEY, mode TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), parameters_json TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, cache_hit INTEGER NOT NULL DEFAULT 0, error_code TEXT);
CREATE TABLE IF NOT EXISTS business_leads (id TEXT PRIMARY KEY, search_run_id TEXT REFERENCES search_runs(id), public_name TEXT NOT NULL, category TEXT, address TEXT, neighborhood TEXT, city TEXT NOT NULL, latitude REAL, longitude REAL, source_url TEXT NOT NULL, website TEXT, website_status TEXT NOT NULL, collected_at TEXT NOT NULL, criteria_json TEXT NOT NULL, confidence TEXT NOT NULL, review_status TEXT NOT NULL, is_mock INTEGER NOT NULL DEFAULT 0, notes TEXT, retention_until TEXT, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS public_requests (id TEXT PRIMARY KEY, search_run_id TEXT REFERENCES search_runs(id), public_name TEXT NOT NULL, category TEXT, area TEXT, source_url TEXT NOT NULL, public_text TEXT, collected_at TEXT NOT NULL, criteria_json TEXT NOT NULL, confidence TEXT NOT NULL, review_status TEXT NOT NULL, is_mock INTEGER NOT NULL DEFAULT 0, notes TEXT, retention_until TEXT, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, business_lead_id TEXT REFERENCES business_leads(id), public_request_id TEXT REFERENCES public_requests(id), source_id TEXT NOT NULL REFERENCES sources(id), source_url TEXT NOT NULL, excerpt TEXT, criterion TEXT NOT NULL, collected_at TEXT NOT NULL, CHECK ((business_lead_id IS NOT NULL) != (public_request_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS deduplication_keys (key TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, normalized_value TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
